            {"metric": "소요시간 단축 폭 (관찰)", "value": "22~25", "value_kind": "range", "unit": "ms", "condition": "make_zero_matrix/make_zero_vector CPU 회귀 후 mempool + warmup, CROWN Verification, eps=1e-06", "element_ids": ["p19:e142"]},
